-- FraudScheme exemplars (v1.6): relaxed detector, multi-scheme matching
-- Derived from 1332 case-relevant classified press articles

SET search_path TO ramona, public;

CREATE TABLE IF NOT EXISTS fraudscheme_exemplars (
    exemplar_id   BIGSERIAL PRIMARY KEY,
    scheme_code   TEXT NOT NULL,
    example_rank  SMALLINT NOT NULL,
    title         TEXT NOT NULL,
    outlet        TEXT,
    url           TEXT,
    country       TEXT,
    exploit_hint  TEXT,
    UNIQUE (scheme_code, url)
);

ON CONFLICT (scheme_code, url) DO NOTHING;